INSERT INTO users(login,password_hash,name,role,email) VALUES('admin',crypt('admin123',gen_salt('bf',12)),'Admin','admin','admin@example.com'),('user',crypt('user123',gen_salt('bf',12)),'User','user','user@example.com'),('manager',crypt('manager123',gen_salt('bf',12)),'Manager','manager','manager@example.com') ON CONFLICT(login) DO UPDATE SET password_hash=EXCLUDED.password_hash,role=EXCLUDED.role,name=EXCLUDED.name,email=EXCLUDED.email;
